 7	    static int binarySearch(int[] sortedNumbers, int target) {
 8	        int low = 0;
 9	        int high = sortedNumbers.length - 1;
10	
11	        while (low <= high) {
12	            int mid = low + (high - low) / 2;
13	            int value = sortedNumbers[mid];
14	
15	            if (value == target) {
16	                return mid;
17	            }
18	
19	            if (value < target) {
20	                low = mid + 1;
21	            } else {
22	                high = mid - 1;
23	            }
24	        }
25	
26	        return NOT_FOUND;
27	    }
